// ─── File: StrategyDemo.java ───
package com.bank.strategy;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class StrategyDemo {
    private static final Logger log = Logger.getLogger(StrategyDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CheckoutService checkout = new CheckoutService();

        // Runtime selection: Rajesh pays by UPI, Priya pays by CARD
        checkout.checkout("UPI", "SAV2001", new BigDecimal("50000"));
        checkout.checkout("CARD", "CUR3001", new BigDecimal("12000"));
        checkout.checkout("NETBANKING", "SAV2001", new BigDecimal("3000"));

        // OPEN/CLOSED: add WALLET as a lambda strategy — NO edit to existing code
        checkout.register("WALLET", amount ->
            Logger.getLogger("PAY").info("WALLET charge Rs." + amount));
        checkout.checkout("WALLET", "SAV2001", new BigDecimal("500"));

        // Java stdlib Strategy: Comparator plugs a comparison algorithm into sort
        List<BigDecimal> amounts = new ArrayList<>(List.of(
            new BigDecimal("500"), new BigDecimal("50000"), new BigDecimal("3000")));
        amounts.sort(Comparator.naturalOrder());    // Strategy from the JDK
        log.info(() -> "Sorted amounts: " + amounts);
    }
}

// ─── STRATEGY INTERFACE (functional, so lambdas work too) ───
@FunctionalInterface
interface PaymentStrategy { void pay(BigDecimal amount); }

// ─── CONCRETE STRATEGIES ───
class UpiPayment implements PaymentStrategy {
    public void pay(BigDecimal amount) { Logger.getLogger("PAY").info("UPI charge Rs." + amount); }
}
class CardPayment implements PaymentStrategy {
    public void pay(BigDecimal amount) { Logger.getLogger("PAY").info("CARD charge Rs." + amount + " (+2% MDR)"); }
}
class NetBankingPayment implements PaymentStrategy {
    public void pay(BigDecimal amount) { Logger.getLogger("PAY").info("NETBANKING debit Rs." + amount); }
}

// ─── CONTEXT: holds strategies in a map, selects at runtime ───
class CheckoutService {
    private static final Logger log = Logger.getLogger(CheckoutService.class.getName());
    private final Map<String, PaymentStrategy> registry = new HashMap<>();
    CheckoutService() {
        registry.put("UPI", new UpiPayment());
        registry.put("CARD", new CardPayment());
        registry.put("NETBANKING", new NetBankingPayment());
    }
    void register(String key, PaymentStrategy strategy) { registry.put(key, strategy); }  // OCP hook
    void checkout(String method, String accountId, BigDecimal amount) {
        PaymentStrategy strategy = registry.get(method);
        if (strategy == null) throw new IllegalArgumentException("Unknown method: " + method);
        log.info(() -> "Account " + accountId + " paying via " + method);
        strategy.pay(amount);     // context delegates, never knows which concrete class
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
